import{t as e}from"./buildPage-DWQZYYcs.js";function t({slug:t,heroTitle:n,roleLabel:r,inputUrlCta:i=`Find my roles`,inputUrlPlaceholder:a=`e.g. linkedin.com/in/yourprofile`}){return e({slug:t,heroTitle:n,heroSubtitle:`Perplexity Computer searches LinkedIn, company career pages, and specialist boards for ${r} openings, ranks the best fits, and builds your application plan automatically.`,inputUrlCta:i,inputUrlPlaceholder:a,inputUrlPrefill:`Use {url} as the starting context for my background, target companies, and job criteria. Then run a comprehensive search for ${r} roles across LinkedIn, company career pages, and niche job boards. 1) Identify open roles that match my seniority, location preferences, and functional focus. 2) Prioritize opportunities posted in the last 14 days and flag the highest-signal openings first. 3) Score each role for fit based on title match, company quality, compensation clues, and likely interview competitiveness. 4) For the strongest matches, extract the title, company, location, posting date, direct apply link, and any referral or networking angle worth pursuing. 5) Summarize why each role is a fit and what I should emphasize in my application. 6) Deliver a prioritized job tracker with next steps, outreach notes, and interview prep talking points.`,heroOverlaySteps:[`Scanning LinkedIn, company sites, and niche boards for ${r} openings`,`Ranking roles by fit, recency, and likelihood of landing an interview`,`Pulling direct apply links, hiring signals, and networking angles`,`Prioritized application tracker and prep notes ready to use`],generatingSteps:[`Reading {url} to understand your background and target ${r} roles`,`Designing an agent to search job boards, company sites, and role-specific communities`,`Configuring fit scoring, recency filters, and networking signal detection`,`Setting up your prioritized tracker with apply links and interview prep notes`],featureSectionTitle:`From profile to interview pipeline`,featureCardTitles:[`Connects to your career stack`,`Outputs you can apply with`],featureCardDescriptions:[`Computer breaks your search into sourcing, scoring, outreach, and prep work, then assigns each step to the model that handles it best.`,`LinkedIn, Gmail, Google Sheets, Notion, and Drive all plug into one workflow so your search, tracker, and outreach stay in sync.`,`Shortlisted roles, direct application links, referral ideas, and interview talking points all come back organized and ready to use.`],capabilitySectionTitle:`Your job search agent, on autopilot`,capabilitySectionSubtitle:`Paste your profile or search criteria, step away, and come back to a ranked pipeline.`,capabilityCards:[{title:`Role Discovery`,description:`Computer can search the web, company career pages, and specialist boards for ${r} roles that actually match your background.`},{title:`Fit Scoring`,description:`Computer can rank every opening by title match, seniority, location, hiring signal, and likely competitiveness so you focus on the right roles first.`},{title:`Application Plan`,description:`Computer can package the best matches into a tracker with direct apply links, deadlines, and notes on what to emphasize in your application.`},{title:`Connect Your Tools`,description:`Computer can sync results into Sheets, Notion, Gmail, and Drive so your search, outreach, and prep all happen in one place.`},{title:`Remember & Learn`,description:`Computer can remember your target roles, preferred companies, and past applications so each new search gets sharper over time.`},{title:`Interview Readiness`,description:`Computer can surface outreach angles, likely interview themes, and fresh openings on a recurring cadence so your pipeline keeps moving.`}]})}export{t};
